/* ============================================
   BUTTON GROUP COMPONENT
   Container for grouped buttons in nav/subnav
   ============================================ */

.ds-button-group {
  /* Layout */
  display: inline-flex; /* Hug content instead of stretch */
  width: auto; /* Don't stretch to full width */
  overflow: hidden;
}

/* ============================================
   HORIZONTAL ORIENTATION
   Default for top navigation
   ============================================ */

.ds-button-group--horizontal {
  flex-direction: row;
  gap: var(--gap-500); /* Figma: --gap/lg (20px) */
  align-items: flex-start;
}

/* ============================================
   VERTICAL ORIENTATION
   For subnav/mobile navigation
   ============================================ */

.ds-button-group--vertical {
  flex-direction: column;
  gap: var(--gap-050); /* 2px */
  align-items: flex-start; /* Left-aligned, hug content */
}

/* Vertical buttons hug their content by default */
.ds-button-group--vertical .ds-button {
  width: auto; /* Hug content instead of stretch */
  display: inline-flex; /* Hug content */
}

import React from 'react';
import { Button, type ButtonProps } from '../Button/Button';
import './ButtonGroup.css';

export interface ButtonGroupProps {
  /** Orientation of the button group */
  orientation?: 'horizontal' | 'vertical';
  /** Array of button configurations */
  buttons: Array<ButtonProps>;
  /** Accessible label for the group */
  ariaLabel?: string;
  /** Additional CSS class */
  className?: string;
}

export const ButtonGroup: React.FC<ButtonGroupProps> = ({
  orientation = 'horizontal',
  buttons,
  ariaLabel,
  className = '',
}) => {
  return (
    <div
      className={`ds-button-group ds-button-group--${orientation} ${className}`}
      role="group"
      aria-label={ariaLabel}
    >
      {/* Spread the whole config so every ButtonProps field (target, rel,
          disabled, …) reaches the Button — enumerating silently dropped them.
          Entries default to tertiary; the deprecated priority spelling still
          counts as an explicit choice. */}
      {buttons.map((button, index) => (
        <Button
          key={index}
          {...button}
          variant={button.variant ?? button.priority ?? 'tertiary'}
        />
      ))}
    </div>
  );
};
